fn is_sorted(arr: &Vec<i32>) -> bool {
    // For a nondecreasing array, it is necessary and sufficient that
    // every adjacent pair satisfies arr[k] <= arr[k+1].
    for k in 0..(arr.len() - 1) {
        if arr[k] > arr[k + 1] {
            return false;
        }
    }
    true
}